*{box-sizing:border-box} :root{--ink:#f4f4ec;--muted:#a9b0a7;--lime:#c8f169;--dark:#101714;--panel:rgba(17,25,22,.86);--line:rgba(255,255,255,.13)} html,body,#game{width:100%;height:100%;margin:0;overflow:hidden;background:#151d1a;color:var(--ink);font-family:'DM Sans',sans-serif} body{overscroll-behavior:none} #world{display:block;width:100%;height:100%;touch-action:none}.vignette{position:absolute;inset:0;pointer-events:none;background:radial-gradient(ellipse at 50% 46%,transparent 40%,rgba(5,10,8,.35) 100%),linear-gradient(180deg,rgba(8,13,11,.2),transparent 30%,transparent 65%,rgba(8,13,11,.38)}
.start-screen{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;background:linear-gradient(90deg,rgba(7,15,12,.87),rgba(8,17,13,.44) 48%,rgba(5,10,9,.06)),linear-gradient(0deg,rgba(8,13,11,.44),transparent 42%);transition:opacity .65s,visibility .65s}.start-screen.closed{opacity:0;visibility:hidden}.intro-card{width:min(440px,calc(100vw - 42px));margin-left:-min(48vw,650px);margin-top:-2vh}.brand-mark{font-size:23px;font-weight:800;letter-spacing:-2px;margin-bottom:54px}.brand-mark span,.brand-small span{color:var(--lime)}.eyebrow{font:500 10px 'DM Mono',monospace;letter-spacing:1.55px;color:var(--lime)}h1{font-size:clamp(54px,7vw,86px);line-height:.91;letter-spacing:-5px;margin:18px 0 20px;font-weight:700}h1 em,.career-drawer h2 em,.map-drawer h2 em{font-family:Georgia,serif;font-weight:400;color:var(--lime);letter-spacing:-3px}.intro-card p{color:#c3cbc3;font-size:15px;margin:0 0 32px}.name-label{display:block;color:#aab4aa;font:500 9px 'DM Mono';letter-spacing:1.2px;margin-bottom:9px}.intro-card input{width:100%;height:48px;padding:0 14px;background:rgba(15,24,20,.62);border:1px solid rgba(255,255,255,.22);color:white;font:500 14px 'DM Sans';outline:none}.intro-card input:focus{border-color:var(--lime)}.primary-button{display:flex;align-items:center;justify-content:space-between;width:100%;height:49px;margin-top:12px;padding:0 17px;border:0;background:var(--lime);color:#152018;font:700 11px 'DM Mono';letter-spacing:1.2px;cursor:pointer;transition:filter .2s,transform .2s}.primary-button:hover{filter:brightness(1.09);transform:translateY(-1px)}.primary-button span{font-size:18px}.microcopy{margin-top:13px;font:9px 'DM Mono';letter-spacing:1px;color:#99a29a}.intro-foot{position:absolute;left:34px;right:34px;bottom:26px;display:flex;justify-content:space-between;color:#c1cbc2;font:9px 'DM Mono';letter-spacing:1.2px}.intro-foot span:last-child{color:#9ba59c}
.hud{position:absolute;inset:0;pointer-events:none}.hidden{display:none!important}.glass{background:var(--panel);border:1px solid rgba(255,255,255,.13);box-shadow:0 8px 36px rgba(0,0,0,.2);backdrop-filter:blur(16px)}.topbar{position:absolute;top:0;left:0;right:0;height:66px;display:flex;align-items:center;padding:0 25px;border-bottom:1px solid rgba(255,255,255,.1);background:linear-gradient(180deg,rgba(10,17,14,.77),rgba(10,17,14,.25));pointer-events:auto}.brand-small{display:flex;align-items:center;gap:12px;font-size:16px;font-weight:800;letter-spacing:-1px}.brand-small b{font:600 10px 'DM Mono';letter-spacing:1.2px;color:#e3e7e0;border-left:1px solid #59615a;padding-left:12px}.region-tag{margin-left:60px;display:flex;align-items:center;gap:9px;font:500 10px 'DM Mono';letter-spacing:1px}.region-tag i,.job-label i{width:7px;height:7px;border-radius:50%;background:var(--lime);box-shadow:0 0 10px var(--lime)}.region-tag small{margin-left:6px;color:#939e94;font-size:8px}.top-right{margin-left:auto;display:flex;align-items:center;gap:22px}.weather{font:10px 'DM Mono';letter-spacing:.8px;color:#d9e3da}.weather span:first-child{font-size:17px;margin-right:7px;color:var(--lime)}.clock{display:flex;flex-direction:column;text-align:right;font:500 14px 'DM Mono'}.clock small{font-size:8px;color:#9da79f;margin-top:2px}.top-right button{width:34px;height:34px;background:transparent;color:#ebeee9;border:1px solid var(--line);font-size:19px;cursor:pointer}.left-stack{position:absolute;top:85px;left:25px;width:272px}.profile-panel{display:flex;align-items:center;padding:13px 14px;gap:12px}.avatar{width:38px;height:38px;background:#a6c970;color:#152019;display:grid;place-items:center;font-size:12px;font-weight:800}.profile-name{font:500 10px 'DM Mono';letter-spacing:.6px}.profile-role{margin-top:4px;font-size:9px;color:#aab4aa}.rank{margin-left:auto;font:500 18px 'DM Mono';text-align:center}.rank small{display:block;font:8px 'DM Mono';color:#99a399}.needs-panel{margin-top:7px;padding:12px 14px}.needs-head{display:flex;justify-content:space-between;margin-bottom:12px;font:9px 'DM Mono';letter-spacing:.8px;color:#aeb8ad}.needs-head span:last-child{font-size:11px;color:var(--lime)}.need-row{display:flex;align-items:center;gap:8px;font:8px 'DM Mono';color:#c1c8c0;margin-top:8px}.need-row>span:first-child{width:48px}.need-row>span:last-child{width:20px;text-align:right;color:#b8c2b9}.meter{height:3px;flex:1;background:#39443b}.meter i{height:100%;width:92%;display:block;background:var(--lime)}.meter.amber i{background:#e5b866;width:84%}
.job-panel{position:absolute;bottom:55px;left:25px;width:352px;padding:17px 18px 14px;background:var(--panel);border:1px solid var(--line);backdrop-filter:blur(16px);pointer-events:auto}.job-label{display:flex;align-items:center;gap:8px;font:9px 'DM Mono';letter-spacing:1px;color:#bbc5bb}.job-label i{width:6px;height:6px}.job-title{font-size:20px;font-weight:600;letter-spacing:-.6px;margin-top:13px}.job-desc{font-size:11px;line-height:1.5;color:#abb4ab;margin-top:4px}.job-objective{display:flex;align-items:center;gap:8px;padding:12px 0 10px;margin-top:10px;border-top:1px solid var(--line);font-size:10px;color:#e1e6df}.objective-dot{width:6px;height:6px;background:var(--lime);border-radius:50%}.distance{margin-left:auto;font:9px 'DM Mono';color:#b4c0b5}.job-progress{height:3px;background:#39443b}.job-progress i{height:100%;width:0;display:block;background:var(--lime);transition:width .4s}.job-footer{display:flex;justify-content:space-between;margin-top:8px;font:8px 'DM Mono';letter-spacing:.7px;color:#9aa59a}.job-footer span:last-child{color:var(--lime)}.controls-hint{position:absolute;right:25px;bottom:27px;display:flex;gap:16px;font:9px 'DM Mono';color:#dce1db;text-shadow:0 1px 5px #000}.controls-hint i{font-style:normal;color:#a6b0a6;margin-left:4px}.interaction{position:absolute;left:50%;top:61%;transform:translate(-50%,-50%);align-items:center;gap:9px;padding:8px 12px;background:rgba(10,16,13,.78);border:1px solid rgba(255,255,255,.18);font:9px 'DM Mono';letter-spacing:.7px;white-space:nowrap}.keycap{display:grid;place-items:center;width:22px;height:22px;background:var(--lime);color:#152018;font:700 11px 'DM Mono'}.toast{position:absolute;left:50%;top:19%;transform:translateX(-50%);padding:11px 17px;background:#c8f169;color:#172117;font:600 10px 'DM Mono';letter-spacing:.5px;box-shadow:0 6px 24px #0005;animation:toastIn .25s ease-out}@keyframes toastIn{from{opacity:0;transform:translate(-50%,-8px)}to{opacity:1;transform:translate(-50%,0)}}
.career-drawer,.map-drawer{position:absolute;right:24px;top:83px;width:min(380px,calc(100vw - 30px));padding:25px 24px 23px;pointer-events:auto}.drawer-close{position:absolute;right:15px;top:12px;color:#cbd2c9;background:transparent;border:0;font-size:26px;cursor:pointer}.career-drawer h2,.map-drawer h2{font-size:33px;line-height:1.03;letter-spacing:-1.6px;margin:13px 0 12px}.career-drawer h2 em,.map-drawer h2 em{letter-spacing:-1.3px}.drawer-intro{font-size:11px;line-height:1.6;color:#b5beb5;margin:0 0 19px}.career-node{display:flex;align-items:center;gap:12px;padding:12px 0;border-top:1px solid var(--line)}.career-node>span{display:grid;place-items:center;width:28px;height:28px;border:1px solid #687269;color:#aeb8ae;font:10px 'DM Mono'}.career-node.active>span{background:var(--lime);border-color:var(--lime);color:#142016}.career-node div{display:flex;flex-direction:column;gap:4px}.career-node b{font-size:11px;font-weight:600}.career-node small{font-size:9px;color:#9eaa9f}.career-node>i{margin-left:auto;font:8px 'DM Mono';font-style:normal;color:#8e998f}.career-node.active>i{color:var(--lime)}.career-drawer .primary-button{margin-top:19px}.region-list{display:grid;gap:8px;margin:17px 0}.region-card{padding:12px 13px;border:1px solid var(--line);display:flex;align-items:center;gap:11px;background:rgba(255,255,255,.025)}.region-card .region-icon{font-size:19px}.region-card b{display:block;font-size:11px}.region-card small{display:block;font-size:9px;color:#9eaa9f;margin-top:4px}.region-card>span:last-child{margin-left:auto;font:8px 'DM Mono';color:#91a092}.map-note{font:8px 'DM Mono';letter-spacing:.65px;line-height:1.6;color:#a3afa3;padding-top:12px;border-top:1px solid var(--line)}.crosshair{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);width:13px;height:13px;opacity:.5}.crosshair i{position:absolute;display:block;background:#f1f3eb}.crosshair i:first-child{height:1px;left:0;right:0;top:6px}.crosshair i:last-child{width:1px;top:0;bottom:0;left:6px}.bottom-right{position:absolute;right:25px;bottom:53px;display:flex;gap:7px;font:8px 'DM Mono';letter-spacing:.8px;color:#dce1db;text-shadow:0 1px 5px #000}.mobile-controls{display:none;pointer-events:auto}.loading{position:absolute;inset:0;background:#101714;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:15px;font:9px 'DM Mono';letter-spacing:1.7px;color:#d8e2d7}.loader{width:28px;height:28px;border:2px solid #35443a;border-top-color:var(--lime);border-radius:50%;animation:spin .7s linear infinite}@keyframes spin{to{transform:rotate(360deg)}}
@media(max-width:700px){.topbar{height:57px;padding:0 12px}.brand-small{font-size:14px}.brand-small b{font-size:8px;padding-left:8px}.region-tag{margin-left:14px;font-size:8px;gap:5px}.region-tag small{display:none}.top-right{gap:9px}.weather{font-size:8px}.weather span:first-child{font-size:14px;margin-right:3px}.clock{font-size:11px}.clock small{font-size:7px}.top-right button{width:29px;height:29px}.left-stack{top:68px;left:10px;width:205px}.profile-panel{padding:9px;gap:8px}.avatar{width:31px;height:31px;font-size:10px}.profile-name{font-size:8px}.profile-role{font-size:8px}.rank{font-size:15px}.needs-panel{padding:9px;margin-top:5px}.needs-head{margin-bottom:8px;font-size:8px}.need-row{font-size:7px;gap:5px}.need-row>span:first-child{width:40px}.job-panel{left:10px;bottom:15px;width:min(310px,calc(100% - 20px));padding:12px}.job-title{font-size:17px;margin-top:8px}.job-desc{font-size:10px}.job-objective{padding:9px 0 8px;margin-top:8px;font-size:9px}.job-footer{font-size:7px}.controls-hint{display:none}.bottom-right{right:12px;bottom:128px;font-size:7px}.career-drawer,.map-drawer{right:8px;top:64px;width:min(355px,calc(100vw - 16px));max-height:calc(100vh - 75px);overflow:auto;padding:21px 18px}.career-drawer h2,.map-drawer h2{font-size:28px}.mobile-controls{display:block;position:absolute;inset:auto 0 10px 0;height:125px;pointer-events:none}.dpad{position:absolute;left:12px;bottom:0;display:flex;flex-direction:column;align-items:center;gap:3px}.dpad>button,.dpad div button,.action-pad button{pointer-events:auto;width:39px;height:36px;border:1px solid #ffffff44;background:#111b17b8;color:white;border-radius:5px;font-size:15px;touch-action:none}.dpad div{display:flex;gap:3px}.dpad button:active,.action-pad button:active{background:#c8f169;color:#152018}.action-pad{position:absolute;right:13px;bottom:2px;display:flex;align-items:end;gap:6px}.action-pad button{width:47px;height:43px;background:#111b17d9;font:9px 'DM Mono';font-weight:bold}.action-pad #touch-interact{background:#c8f169;color:#152018;width:51px;height:51px;border-radius:50%}.intro-card{margin:0 0 0 0}.brand-mark{margin-bottom:36px}.intro-foot{left:14px;right:14px;bottom:15px;font-size:7px}.intro-foot span:last-child{max-width:48%;text-align:right}.interaction{top:58%}.crosshair{top:48%}}

import * as THREE from 'three';

const canvas=document.querySelector('#world');
const renderer=new THREE.WebGLRenderer({canvas,antialias:true,powerPreference:'high-performance'});
renderer.setPixelRatio(Math.min(devicePixelRatio,1.8));renderer.setSize(innerWidth,innerHeight);renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.12;
const scene=new THREE.Scene();scene.background=new THREE.Color(0x9ab7bf);scene.fog=new THREE.FogExp2(0x9ab7bf,.00165);
const camera=new THREE.PerspectiveCamera(54,innerWidth/innerHeight,.1,1800);
const hemi=new THREE.HemisphereLight(0xdbeaf0,0x59604a,2.1);scene.add(hemi);
const sun=new THREE.DirectionalLight(0xffe7c2,3.2);sun.position.set(-150,220,100);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);sun.shadow.camera.left=-160;sun.shadow.camera.right=160;sun.shadow.camera.top=160;sun.shadow.camera.bottom=-160;sun.shadow.bias=-.0002;scene.add(sun);sun.target.position.set(0,0,0);scene.add(sun.target);
const mat=(color,roughness=.85,metalness=0)=>new THREE.MeshStandardMaterial({color,roughness,metalness});
const mats={grass:mat(0x647853),grass2:mat(0x72875b),road:mat(0x303a3a),roadEdge:mat(0xb3a98d),line:mat(0xe4ddc4),concrete:mat(0x93958c),steel:mat(0x697778,.45,.65),yellow:mat(0xeab437,.53),orange:mat(0xef762e),white:mat(0xd7d8ce),blue:mat(0x315e76),dark:mat(0x222a28),glass:new THREE.MeshStandardMaterial({color:0x8db4bb,roughness:.27,metalness:.28}),wood:mat(0x776044),foliage:mat(0x3e5a3f),sand:mat(0xb8955e),snow:mat(0xe3e9e9),water:new THREE.MeshStandardMaterial({color:0x3c8291,roughness:.19,metalness:.28}),skin:mat(0xb6815e),pants:mat(0x3e4b46),vest:mat(0xd78235),shirt:mat(0x52645c)};
const boxGeo=new THREE.BoxGeometry(1,1,1),sphereGeo=new THREE.SphereGeometry(1,20,16),cylGeo=new THREE.CylinderGeometry(1,1,1,20),coneGeo=new THREE.ConeGeometry(1,1,16);
function mesh(geo,material,parent=scene){const m=new THREE.Mesh(geo,material);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m}
function block(x,y,z,sx,sy,sz,material,parent=scene){const m=mesh(boxGeo,material,parent);m.position.set(x,y+sy/2,z);m.scale.set(sx,sy,sz);return m}
function ball(x,y,z,sx,sy,sz,material,parent=scene){const m=mesh(sphereGeo,material,parent);m.position.set(x,y,z);m.scale.set(sx,sy,sz);return m}
function cylinder(x,y,z,r,h,material,parent=scene,radial=16){const m=mesh(new THREE.CylinderGeometry(r*.83,r,h,radial),material,parent);m.position.set(x,y+h/2,z);return m}
function road(a,b,width=10){const dx=b[0]-a[0],dz=b[1]-a[1],len=Math.hypot(dx,dz),angle=-Math.atan2(dz,dx),g=new THREE.Group();g.position.set((a[0]+b[0])/2,.035,(a[1]+b[1])/2);g.rotation.y=angle;scene.add(g);block(0,0,0,len,.08,width,mats.road,g);block(0,.01,0,len,.025,.18,mats.roadEdge,g);for(let x=-len/2+5;x<len/2;x+=9)block(x,.055,0,3.2,.018,.12,mats.line,g);return g}
function zoneGround(x,z,size,material){const p=mesh(new THREE.PlaneGeometry(size,size),material);p.rotation.x=-Math.PI/2;p.position.set(x,-.06,z);return p}
zoneGround(0,0,1100,mats.grass);
// Regional terrain fields and the connected state highway network.
const regions=[{name:'Harbor Bay',tag:'COASTAL · HARBOR',icon:'◉',x:0,z:0,desc:'Port, fiber networks & seawall work',color:0x647853},{name:'Iron City',tag:'METROPOLITAN',icon:'▥',x:-190,z:-125,desc:'Downtown vaults & aerial distribution',color:0x66736a},{name:'Cedar Valley',tag:'RURAL · NORTH',icon:'⌁',x:190,z:-125,desc:'Farm communities & rural fiber',color:0x718051},{name:'Summit Ridge',tag:'ALPINE · WEST',icon:'△',x:-190,z:165,desc:'Mountain restoration & rock work',color:0x718184},{name:'Red Mesa',tag:'DESERT · EAST',icon:'◈',x:190,z:165,desc:'Solar, transmission & heavy civil',color:0xa78a59}];
zoneGround(-190,-125,170,mat(0x5b6254));zoneGround(190,-125,170,mat(0x687a4e));zoneGround(-190,165,170,mat(0x536352));zoneGround(190,165,170,mats.sand);
road([-20,0],[-190,-125],13);road([-20,0],[-190,165],13);road([20,0],[190,-125],13);road([20,0],[190,165],13);road([-190,-125],[190,-125],11);road([-190,165],[190,165],11);road([-190,-125],[-190,165],11);road([190,-125],[190,165],11);
// Harbor water, shore edge and broad coastal highway.
const sea=mesh(new THREE.PlaneGeometry(230,260),mats.water);sea.rotation.x=-Math.PI/2;sea.position.set(144,-.15,10);block(91,0,10,5,.35,260,mats.roadEdge);road([86,-125],[86,125],11);
// Distant ridgelines ground the horizon.
for(let i=0;i<20;i++){const x=-480+i*50;const peak=mesh(new THREE.ConeGeometry(42+Math.sin(i*9)*13,75+Math.cos(i*4)*32,7),i%3===0?mats.snow:mat(0x64746b));peak.position.set(x,35,-350-(i%4)*32);peak.scale.z=1.4;peak.castShadow=false}

function makeBuilding(x,z,w,h,d,kind='office',rot=0){const g=new THREE.Group();g.position.set(x,0,z);g.rotation.y=rot;scene.add(g);const wall=kind==='warehouse'?mat(0x85877e):kind==='house'?mat(0xc1bba7):mat(0x777e7a);block(0,0,0,w,h,d,wall,g);block(0,h,0,w+.3,.3,d+.3,mat(kind==='house'?0x454947:0x42494a),g);if(kind!=='warehouse'){const floors=Math.floor(h/3),cols=Math.max(2,Math.floor(w/2.5));for(let f=0;f<floors;f++)for(let c=0;c<cols;c++){let wx=-w/2+(c+.5)*w/cols;for(const side of [-1,1]){const win=block(wx,1.15+f*2.7,side*(d/2+.015),Math.min(1.25,w/cols*.6),1.25,.04,mats.glass,g);win.castShadow=false}}}else{for(let k=0;k<4;k++)block(-w/2+(k+1)*w/5,h*.65,d/2+.02,1.1,1.1,.05,mats.glass,g)}return g}
function makeTree(x,z,scale=1,autumn=false){const g=new THREE.Group();g.position.set(x,0,z);g.scale.setScalar(scale);scene.add(g);cylinder(0,0,0,.24,3.2,mats.wood,g,10);const leaves=autumn?mat(0x987044):new THREE.MeshStandardMaterial({color:[0x3f6043,0x526e47,0x536c50][Math.floor(Math.random()*3)],roughness:1});for(let i=0;i<3;i++){const l=mesh(new THREE.IcosahedronGeometry(1,2),leaves,g);l.position.set((Math.random()-.5)*.8,2.7+i*.62,(Math.random()-.5)*.8);l.scale.set(1.3-i*.16,1.1,1.15-i*.12);l.castShadow=true}return g}
function makeStreetlight(x,z){cylinder(x,0,z,.12,7,mat(0x424c48),scene,10);block(x,6.8,z-1.3,1.8,.12,.14,mat(0x454e49));ball(x,6.7,z-2.1,.27,.12,.18,mat(0xf5dfaa))}
// Build five distinct regional silhouettes.
for(let i=0;i<13;i++)makeBuilding(-220+(i%5)*15,-155+Math.floor(i/5)*17,9+Math.random()*9,12+Math.random()*32,10+Math.random()*8,i%4===0?'warehouse':'office',Math.random()*.15);
for(let i=0;i<25;i++)makeBuilding(150+(i%5)*18,-165+Math.floor(i/5)*18,10,5+Math.random()*3,9,'house',i%2*.06);
for(let i=0;i<35;i++)makeTree(-260+Math.random()*140,95+Math.random()*145,.8+Math.random()*.7);
for(let i=0;i<20;i++)makeTree(120+Math.random()*130,75+Math.random()*150,.8+Math.random()*.6);
for(let i=0;i<12;i++){const b=makeBuilding(145+(i%4)*19,140+Math.floor(i/4)*21,14,7+Math.random()*4,13,'warehouse');b.children[0].material=mats.sand}
// Harbor port: cranes, stacked containers, timber poles and a working utility yard.
for(let i=0;i<12;i++){const c=block(71+(i%4)*4,0,-53+Math.floor(i/4)*10,3.7,2.8,8,[mat(0x9d4334),mat(0x385c61),mat(0xb17b32)][i%3]);block(71+(i%4)*4,2.82,-53+Math.floor(i/4)*10,3.7,.1,8,mats.white)}
for(const x of [68,91]){cylinder(x,0,-45,.55,26,mats.orange,scene,12);block(x+5,25,-45,10,.5,.5,mats.orange);block(x+10,19,-45,.3,12,.3,mats.orange)}
for(let i=0;i<10;i++){let x=-55+i*12;cylinder(x,0,-31,.16,8,mats.wood);cylinder(x,7.3,-31,.08,4,mats.dark);if(i<9){const wire=mesh(new THREE.CylinderGeometry(.035,.035,12,8),mats.dark);wire.position.set(x+6,7.8,-31);wire.rotation.z=Math.PI/2}}
for(let i=0;i<7;i++)makeStreetlight(-31+i*12,18);
// Iron City skyline and cranes.
for(let i=0;i<15;i++){const x=-234+(i%5)*21,z=-110+Math.floor(i/5)*23,w=13+Math.random()*6,h=45+Math.random()*60,d=14+Math.random()*8;makeBuilding(x,z,w,h,d,'office');}
