function showInteraction(item){nearby=item;const el=$('#interaction');if(item){$('#interaction-label').textContent=item.label;el.classList.remove('hidden')}else el.classList.add('hidden')}
const conversationPanel=$('#conversation'),conversationLog=$('#conversation-log'),conversationInput=$('#conversation-input');
let activeConversation=null,speechRecognition=null,speakNextReply=false,foremanOrder=null;
const dialogueMemory=(()=>{try{return JSON.parse(localStorage.getItem('ue-dialogue-memory')||'{}')}catch{return {}}})();
function saveDialogueMemory(){try{localStorage.setItem('ue-dialogue-memory',JSON.stringify(dialogueMemory))}catch{}}
function renderConversation(){if(!activeConversation)return;const memory=dialogueMemory[activeConversation.id]||{messages:[],notes:[]};conversationLog.innerHTML='';for(const entry of memory.messages.slice(-12)){const row=document.createElement('div');row.className='chat-line '+(entry.from==='you'?'from-player':'from-npc');const speaker=document.createElement('b');speaker.textContent=entry.from==='you'?'YOU':activeConversation.name;const text=document.createElement('span');text.textContent=entry.text;row.append(speaker,text);conversationLog.append(row)}conversationLog.scrollTop=conversationLog.scrollHeight;$('#conversation-name').textContent=activeConversation.name;$('#conversation-role').textContent=activeConversation.role;$('#conversation-presence').textContent=activeConversation.id==='dispatcher'?'RADIO LINK · HARBOR BAY':activeConversation.id==='foreman'?'ON SITE · HARBOR BAY CREW':'CREW MEMBER · HARBOR BAY';const note=memory.notes?.at(-1);$('#conversation-log').dataset.memory=note||''}
function addDialogue(from,text){if(!activeConversation)return;const memory=dialogueMemory[activeConversation.id]||(dialogueMemory[activeConversation.id]={messages:[],notes:[]});memory.messages.push({from,text,time:Date.now()});memory.messages=memory.messages.slice(-30);const topic=text.toLowerCase().match(/\b(contract|fiber|trench|safety|crew|equipment|pay|weather|home|truck)\b/)?.[1];if(from==='you'&&topic){memory.notes.push(`Asked about ${topic}`);memory.notes=memory.notes.slice(-8)}saveDialogueMemory();renderConversation();if(from!=='you'&&speakNextReply&&'speechSynthesis'in window){window.speechSynthesis.cancel();window.speechSynthesis.speak(new SpeechSynthesisUtterance(text));speakNextReply=false}}
function openConversation(id='dispatcher'){const identity=id==='foreman'?{id:'foreman',name:'Rosa Chen',role:'CREW FOREMAN'}:id==='dispatcher'?{id:'dispatcher',name:'Maya Brooks',role:'DISPATCH · HARBOR BAY'}:{id,name:'Crew Member',role:'FIELD CREW'};activeConversation=identity;conversationPanel.classList.remove('hidden');renderConversation();if(!(dialogueMemory[id]?.messages?.length)){addDialogue('npc',id==='dispatcher'?'Dispatch here. I can put you on the Harbor Bay fiber repair and keep your work order straight. What do you need?':id==='foreman'?'I’m Rosa, your foreperson. I’ll follow the active work order and stop if a request is unsafe or outside scope.':'Good to see you out here. How is your shift going?')}conversationInput.focus()}
function closeConversation(){conversationPanel.classList.add('hidden');activeConversation=null;if(speechRecognition){speechRecognition.stop();speechRecognition=null}}
