function orderForeman(message){const text=message.toLowerCase();if(/\b(disable|skip|remove|ignore|bypass|enter|go into)\b.{0,35}\b(safety|ppe|shoring|permit|trench|lockout)\b|\b(unsafe|unshored|without (a )?permit)\b/.test(text))return 'No. We do not bypass PPE, permits, shoring, or safe trench access. I will only work the approved scope safely.';const stage=playerState.job;if(stage<1||stage>5)return stage===0?'I’m ready once the dispatcher issues your field kit and active work order.': 'There is no active field step for me right now. Check in with dispatch for the next contract.';const task=taskCommandForStage(stage);const explicit=task.terms.some(term=>text.includes(term));const generic=/\b(do it|go ahead|proceed|handle it|take care of it|complete (the )?(current )?(task|step)|work the order|execute (the )?work order)\b/.test(text);const otherTask=['survey','inspect','excavat','conduit','install','pull','splice','test','restore'].some(term=>text.includes(term)&&!task.terms.some(current=>term.startsWith(current)||current.startsWith(term)));if(otherTask&&!explicit)return `I can't skip ahead. The authorized step is to ${task.name}.`;if(!(explicit||generic))return null;if(foremanOrder)return 'I’m already working the assigned step. I’ll report back when it is complete.';foremanOrder={stage,elapsed:0,arrived:false};return `Understood. I’m heading to the work area to ${task.name}. I’ll report when the site task is done.`}
function dialogueReply(message){const text=message.toLowerCase();if(activeConversation.id==='dispatcher'){if(/\b(assign|accept|take|give me|start|issue)\b.{0,45}\b(work|job|contract|shift|order)\b|\b(put me to work|i want work|ready for work)\b/.test(text)){if(playerState.job<0){playerState.job=0;updateHud();activeMarker();return 'Work order HB-014 is assigned: Harbor Bay fiber repair, $24/hour with a $960 completion bonus. Collect your field kit at the Equipment Depot; your foreperson is Rosa Chen.'}return playerState.job>=6?'You have completed the current order. Report to the Workforce Center to take another contract.':`You already have an active order: ${playerState.job===0?'collect your field kit':jobStages[playerState.job].title}. I’ll keep it open.`}if(/\b(pay|money|rate|bonus)\b/.test(text))return 'This entry-level order pays $24 per hour and a $960 completion bonus. The bonus is deposited when all five approved steps are complete.';if(/\b(status|order|contract|work|job|task)\b/.test(text))return playerState.job<0?'One Harbor Bay fiber repair is available: $24/hour plus a $960 completion bonus. Say “assign me the work order” to accept it.':playerState.job>=6?'HB-014 is complete and paid. Visit the Workforce Center when you are ready for another contract.':`Your active work order is HB-014. ${playerState.job===0?'Pick up the field kit at the Equipment Depot.':`Current step: ${jobStages[playerState.job].title}.`} The work stays within the approved fiber-repair scope.`;if(/\b(crew|foreman|rosa)\b/.test(text))return 'Rosa Chen is the on-site foreperson. She can carry out the current authorized step, but not skip inspections or safety requirements.';if(/\b(weather|rain|conditions)\b/.test(text))return 'Conditions can change during the shift. Pause work if the site becomes unsafe, and check the field markers before proceeding.';return 'I can assign your first Harbor Bay order, explain pay, or confirm the active work step. What would help?'}if(activeConversation.id=