function dialogueReply
function dialogueReply(message){const text=message.toLowerCase();if(activeConversation.id==='dispatcher'){if(/\b(assign|accept|take|give me|start|issue)\b.{0,45}\b(work|job|contract|shift|order)\b|\b(put me to work|i want work|ready for work)\b/.test(text)){if(playerState.job<0){playerState.job=0;updateHud();activeMarker();return 'Work order HB-014 is assigned: Harbor Bay fiber repair, $24/hour with a $960 completion bonus. Collect your field kit at the Equipment Depot; your foreperson is Rosa Chen.'}return playerState.job>=6?'You have completed the current order. Report to the Workforce Center to take another contract.':`You already have an active order: ${playerState.job===0?'collect your field kit':jobStages[playerState.job].title}. I’ll keep it open.`}if(/\b(pay|money|rate|bonus)\b/.test(text))return 'This entry-level order pays $24 per hour and a $960 completion bonus. The bonus is deposited when all five approved steps are complete.';if(/\b(status|order|contract|work|job|task)\b/.test(text))return playerState.job<0?'One Harbor Bay fiber repair is available: $24/hour plus a $960 completion bonus. Say “assign me the work order” to accept it.':playerState.job>=6?'HB-014 is complete and paid. Visit the Workforce Center when you are ready for another contract.':`Your active work order is HB-014. ${playerState.job===0?'Pick up the field kit at the Equipment Depot.':`Current step: ${jobStages[playerState.job].title}.`} The work stays within the approved fiber-repair scope.`;if(/\b(crew|foreman|rosa)\b/.test(text))return 'Rosa Chen is the on-site foreperson. She can carry out the current authorized step, but not skip inspections or safety requirements.';if(/\b(weather|rain|conditions)\b/.test(text))return 'Conditions can change during the shift. Pause work if the site becomes unsafe, and check the field markers before proceeding.';return 'I can assign your first Harbor Bay order, explain pay, or confirm the active work step. What would help?'}if(activeConversation.id==='foreman'){const command=orderForeman(message);if(command)return command;if(/\b(memory|remember|last time|before)\b/.test(text)){const note=dialogueMemory.foreman?.notes?.slice(-2).join('; ');return note?`I remember from our earlier conversations: ${note}. I’m still tracking the current work order.`:'I’ll keep a short shift log on this device. So far, we’re focused on the approved Harbor Bay work order.'}if(/\b(safety|safe|permit|ppe|hazard|shoring)\b/.test(text))return 'Safety first: keep PPE on, use the marked access, and stop if the trench or weather is unsafe. I will not bypass permits, shoring, or inspections.';if(/\b(status|task|order|work|progress)\b/.test(text))return playerState.job<1||playerState.job>5?'We need an active field work order before I can direct the crew.':`I’m assigned to ${taskCommandForStage(playerState.job).name}. Tell me “go ahead” to have me perform that step.`;return 'I’m keeping to the approved work order. Ask about safety, the active task, or direct me to perform the current authorized step.'}if(/\b(memory|remember|before)\b/.test(text)){const note=dialogueMemory[activeConversation.id]?.notes?.slice(-1)[0];return note?`I remember you mentioned ${note.toLowerCase()}. Good to see you again.`:'I’ll remember the useful details from our shift conversations on this device.'}return 'I’m on the Harbor Bay crew. Check with Rosa for the current work step or use the radio to reach dispatch.'}

